// ─── Helpers ───
function calcCartTotals(cart, restaurant) {
  const subtotal = cart.reduce((s, line) => s + line.qty * line.basePrice, 0);
  const rate = restaurant?.baseRate || 0;
  const baseBites = Math.round(subtotal * rate);
  const welcomeBonus = Math.round(baseBites); // Welcome 2X effectively doubles
  const totalBites = baseBites + welcomeBonus;
  return { subtotal, baseBites, welcomeBonus, totalBites };
}

function getItemById(restaurantKey, itemId) {
  return MENUS[restaurantKey].items.find(i => i.id === itemId);
}

function getDietaryCoverage(profile) {
  const total = profile.dietaryRestrictions.length;
  const covered = profile.dietaryRestrictions.filter(r => r.count > 0 || r.source === "learned").length;
  return { total, covered, ratio: covered / Math.max(total, 1) };
}

// ─── Small UI primitives ───
function CountUp({ value, duration = 700, format = (v) => Math.round(v).toLocaleString() }) {
  const [display, setDisplay] = useState(value);
  const prevValue = useRef(value);
  useEffect(() => {
    const start = prevValue.current;
    const startTime = performance.now();
    let frameId;
    const tick = (now) => {
      const elapsed = now - startTime;
      const progress = Math.min(elapsed / duration, 1);
      const eased = 1 - Math.pow(1 - progress, 3);
      setDisplay(start + (value - start) * eased);
      if (progress < 1) frameId = requestAnimationFrame(tick);
      else prevValue.current = value;
    };
    frameId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frameId);
  }, [value, duration]);
  return <span>{format(display)}</span>;
}

function Bar({ pct, color, bg, height = 6 }) {
  return (
    <div style={{ height, background: bg || T.borderLight, borderRadius: 99, overflow: "hidden" }}>
      <div style={{
        width: `${Math.min(Math.max(pct, 0), 100)}%`, height: "100%",
        background: color, borderRadius: 99, transition: "width 0.5s cubic-bezier(0.4,0,0.2,1)",
      }} />
    </div>
  );
}

// MenuItemImage — touched-up food photo with Starbucks-inspired branded backdrop.
// Strategic principles:
//   1. Images appear at decide/confirm/celebrate moments only
//   2. Brand-colored container behind the photo unifies disparate stock photography
//      (in production, restaurants supply photos that go through a touch-up pipeline
//      with this same treatment baked in)
//   3. Graceful emoji fallback ensures broken loads, low bandwidth, or missing data
//      never break the UI
function MenuItemImage({ item, fallbackIcon, size = 64, rounded = 10, mode = "thumb", brandColor, brandColorAccent }) {
  const [error, setError] = useState(false);

  // Default to neutral surface gradient if no brand color provided
  const containerBg = brandColor && brandColorAccent
    ? `linear-gradient(135deg, ${brandColor}, ${brandColorAccent})`
    : `linear-gradient(135deg, ${T.brandLight}, ${T.surfaceAlt})`;

  const isHero = mode === "hero";
  const inset = isHero ? 0 : 4; // hero images fill edge-to-edge; thumbs get a brand-color halo

  const containerStyle = {
    width: isHero ? "100%" : size,
    height: size,
    borderRadius: rounded,
    background: containerBg,
    border: brandColor ? "none" : `1px solid ${T.border}`,
    overflow: "hidden",
    position: "relative",
    flexShrink: 0,
    padding: inset,
    boxSizing: "border-box",
  };

  // Fallback: brand-tinted container with emoji centered
  if (!item?.imageUrl || error) {
    return (
      <div style={{ ...containerStyle, display: "flex", alignItems: "center", justifyContent: "center", padding: 0 }}>
        <span style={{ fontSize: size * 0.5, filter: brandColor ? "drop-shadow(0 2px 6px rgba(0,0,0,0.25))" : "none" }}>
          {fallbackIcon || "🍽️"}
        </span>
      </div>
    );
  }

  return (
    <div style={containerStyle}>
      <img
        src={item.imageUrl}
        alt={item.name || ""}
        loading="lazy"
        onError={() => setError(true)}
        style={{
          width: "100%",
          height: "100%",
          borderRadius: Math.max(rounded - inset, 4),
          objectFit: "cover",
          display: "block",
        }}
      />
      {/* Subtle brand-tint overlay — pulls photos toward restaurant identity without obscuring food */}
      {brandColor && (
        <div style={{
          position: "absolute", inset: inset,
          borderRadius: Math.max(rounded - inset, 4),
          background: `linear-gradient(135deg, ${brandColor}1A 0%, transparent 45%, ${brandColor}26 100%)`,
          pointerEvents: "none",
          mixBlendMode: "multiply",
        }} />
      )}
    </div>
  );
}

