// ─── Tier 3 light cart — generic categories with price ranges, no modifiers, no qty steppers ───
function TierThreeLightCart({ restaurant, profile }) {
  const minTotal = restaurant.estimatedCart.reduce((s, l) => s + l.ppMin * profile.headcount, 0);
  const maxTotal = restaurant.estimatedCart.reduce((s, l) => s + l.ppMax * profile.headcount, 0);
  const minPp = minTotal / profile.headcount;
  const maxPp = maxTotal / profile.headcount;
  // Bites projection — faded, hypothetical
  const midTotal = (minTotal + maxTotal) / 2;
  const estBitesBase = Math.round(midTotal * restaurant.estimatedBaseRate);
  const estBitesWelcome = estBitesBase; // Welcome 2X projection
  const estBitesTotal = estBitesBase + estBitesWelcome;

  return (
    <>
      {/* Faded Bites projection — replaces the StatusRibbon for Tier 3 */}
      <div style={{
        background: T.card, borderRadius: 14, border: `1px dashed ${T.border}`,
        padding: "14px 18px", marginBottom: 14,
        opacity: 0.85,
      }}>
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1.2fr 1fr", gap: 24, alignItems: "center" }}>

          {/* Faded Bites projection */}
          <div>
            <div style={{ fontSize: 10, fontWeight: 700, color: T.textTertiary, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 4, fontFamily: fontDisplay }}>
              🎁 You'd earn (if activated)
            </div>
            <div style={{ display: "flex", alignItems: "baseline", gap: 6 }}>
              <span style={{ fontSize: 20, fontWeight: 600, color: T.textTertiary, fontFamily: fontDisplay, letterSpacing: "-0.01em" }}>
                ~{estBitesTotal.toLocaleString()}
              </span>
              <span style={{ fontSize: 11, color: T.textTertiary }}>
                Bites · ≈ ${(estBitesTotal/100).toFixed(2)}
              </span>
            </div>
            <div style={{ fontSize: 10, color: T.textTertiary, marginTop: 2, fontStyle: "italic" }}>
              Estimated · earn rate confirmed at activation
            </div>
          </div>

          {/* Estimated price range */}
          <div>
            <div style={{ fontSize: 10, fontWeight: 700, color: T.textTertiary, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 4, fontFamily: fontDisplay }}>
              Estimated price range
            </div>
            <div style={{ fontSize: 14, fontWeight: 700, color: T.text, fontFamily: fontMono }}>
              ${minTotal.toFixed(0)} – ${maxTotal.toFixed(0)}
            </div>
            <div style={{ fontSize: 10, color: T.textTertiary, marginTop: 2 }}>
              ${minPp.toFixed(2)} – ${maxPp.toFixed(2)}/pp · final price from restaurant
            </div>
          </div>

          {/* Status */}
          <div>
            <div style={{ fontSize: 10, fontWeight: 700, color: T.textTertiary, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 4, fontFamily: fontDisplay }}>
              Status
            </div>
            <div style={{
              display: "inline-flex", alignItems: "center", gap: 5,
              padding: "3px 8px", borderRadius: 5,
              background: T.warningBg, color: T.warning,
              fontSize: 11, fontWeight: 600,
            }}>
              <span>📍</span> Not yet partnered
            </div>
            <div style={{ fontSize: 10, color: T.textTertiary, marginTop: 4 }}>
              Order via quote or direct contact
            </div>
          </div>
        </div>
      </div>

      {/* Estimated line items — minimal, no modifiers/qty */}
      {restaurant.estimatedCart.map(line => (
        <div key={line.id} style={{
          background: T.card, borderRadius: 12, border: `1px dashed ${T.border}`,
          padding: 14, marginBottom: 10,
        }}>
          <div style={{ display: "grid", gridTemplateColumns: "1fr auto", gap: 14, alignItems: "flex-start" }}>
            <div>
              <div style={{ fontSize: 14, fontWeight: 600, color: T.text, fontFamily: fontDisplay, marginBottom: 3 }}>
                {line.desc}
              </div>
              <div style={{ fontSize: 11, color: T.textSecondary, lineHeight: 1.5, marginBottom: 8 }}>
                {line.detail}
              </div>
              <span style={{ fontSize: 11, color: T.textTertiary, display: "inline-flex", alignItems: "center", gap: 5 }}>
                <span style={{ fontSize: 12 }}>👥</span>
                {line.coverage}
              </span>
            </div>
            <div style={{ textAlign: "right", minWidth: 110 }}>
              <div style={{ fontSize: 14, fontWeight: 700, color: T.text, fontFamily: fontMono }}>
                ${(line.ppMin * profile.headcount).toFixed(0)}–${(line.ppMax * profile.headcount).toFixed(0)}
              </div>
              <div style={{ fontSize: 10, color: T.textTertiary, marginTop: 2 }}>
                ${line.ppMin.toFixed(2)}–${line.ppMax.toFixed(2)}/pp
              </div>
            </div>
          </div>
        </div>
      ))}

      {/* Helper note */}
      <div style={{
        padding: "10px 14px", borderRadius: 10,
        background: T.warningBg, border: `1px solid ${T.warning}33`,
        marginTop: 4, marginBottom: 10,
        display: "flex", alignItems: "center", gap: 10,
      }}>
        <span style={{ fontSize: 14 }}>💡</span>
        <span style={{ flex: 1, fontSize: 11, color: T.textSecondary, lineHeight: 1.5 }}>
          This is an estimate based on category averages. Final menu, modifiers, and pricing come from the restaurant when they respond to your quote or call.
        </span>
      </div>
    </>
  );
}

