// ─── Cart line item (group-level) ───
function CartLineItem({ line, restaurantKey, onChange, onRemove, onCustomizePerPerson }) {
  const item = getItemById(restaurantKey, line.itemId);
  if (!item) return null;
  const lineTotal = line.qty * line.basePrice;
  const hasOverrides = (line.perPersonOverrides || []).length > 0;
  const restaurant = MENUS[restaurantKey];

  const stepBtn = {
    width: 26, height: 26, borderRadius: 7, border: `1px solid ${T.border}`,
    background: T.card, color: T.text, fontSize: 13, fontWeight: 600, cursor: "pointer",
    display: "flex", alignItems: "center", justifyContent: "center", fontFamily: font,
    transition: "all 0.1s",
  };

  return (
    <div style={{
      background: T.card, borderRadius: 12, border: `1px solid ${T.border}`,
      padding: 14, marginBottom: 10, transition: "all 0.2s",
    }}>
      <div style={{ display: "grid", gridTemplateColumns: "auto 1fr auto", gap: 14, alignItems: "flex-start" }}>

        {/* Thumbnail — visual confirmation, with brand-color backdrop for unified look */}
        <MenuItemImage
          item={item}
          fallbackIcon={restaurant.icon}
          size={72}
          rounded={10}
          brandColor={restaurant.brandColor}
          brandColorAccent={restaurant.brandColorAccent}
        />

        {/* Item details */}
        <div style={{ minWidth: 0 }}>
          <div style={{ display: "flex", alignItems: "baseline", gap: 8, marginBottom: 4, flexWrap: "wrap" }}>
            <span style={{ fontSize: 14, fontWeight: 600, color: T.text, fontFamily: fontDisplay }}>{item.name}</span>
            <span style={{ fontSize: 11, color: T.textTertiary, fontFamily: fontMono }}>${line.basePrice.toFixed(2)} ea</span>
            {item.dietaryFlags?.includes("contains-nuts") && (
              <span style={{ fontSize: 9, padding: "2px 6px", borderRadius: 4, background: T.warningBg, color: T.warning, fontWeight: 700, letterSpacing: "0.04em" }}>
                CONTAINS NUTS
              </span>
            )}
          </div>
          <div style={{ fontSize: 11, color: T.textSecondary, marginBottom: 10 }}>{item.desc}</div>

          {/* Modifier chips */}
          {item.modifierGroups && item.modifierGroups.length > 0 && (
            <div style={{ display: "flex", flexWrap: "wrap", gap: 6, marginBottom: 10 }}>
              {item.modifierGroups.map(g => (
                <ModifierChip
                  key={g.id}
                  groupName={g.name}
                  value={line.modifiers[g.id]}
                  options={g.options}
                  multi={g.multi}
                  onChange={(v) => onChange({ ...line, modifiers: { ...line.modifiers, [g.id]: v } })}
                />
              ))}
            </div>
          )}

          {/* Qty stepper + applies-to + per-person */}
          <div style={{ display: "flex", alignItems: "center", gap: 12, flexWrap: "wrap" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 6, padding: "2px", background: T.surface, borderRadius: 8 }}>
              <button onClick={() => line.qty > 1 ? onChange({ ...line, qty: line.qty - 1 }) : onRemove()} style={stepBtn} title={line.qty === 1 ? "Remove item" : "Decrease quantity"}>−</button>
              <span style={{ fontSize: 13, fontWeight: 700, color: T.text, fontFamily: fontMono, minWidth: 24, textAlign: "center" }}>
                {line.qty}
              </span>
              <button onClick={() => onChange({ ...line, qty: line.qty + 1 })} style={stepBtn} title="Increase quantity">＋</button>
            </div>
            <span style={{ fontSize: 11, color: T.textTertiary, display: "flex", alignItems: "center", gap: 5 }}>
              <span style={{ fontSize: 12 }}>👥</span>
              {line.appliesTo}
            </span>
            {hasOverrides && (
              <span style={{ fontSize: 10, padding: "2px 7px", borderRadius: 4, background: T.purpleBg, color: T.purple, fontWeight: 600 }}>
                ✦ {line.perPersonOverrides.length} per-person customization
              </span>
            )}
            <button onClick={onCustomizePerPerson} style={{
              padding: "3px 8px", borderRadius: 6, border: "none", background: "transparent",
              color: T.brand, fontSize: 11, fontWeight: 600, cursor: "pointer", fontFamily: font,
              display: "flex", alignItems: "center", gap: 4, marginLeft: "auto",
            }}>
              Customize individual orders →
            </button>
          </div>
        </div>

        {/* Line total */}
        <div style={{ textAlign: "right", minWidth: 80 }}>
          <div style={{ fontSize: 16, fontWeight: 700, color: T.text, fontFamily: fontMono }}>
            ${lineTotal.toFixed(2)}
          </div>
          <div style={{ fontSize: 10, color: T.textTertiary, marginTop: 2 }}>
            {Math.round(lineTotal * MENUS[restaurantKey].baseRate * 2).toLocaleString()} Bites
          </div>
        </div>
      </div>
    </div>
  );
}

// ─── Per-person customization table (overlay) ───
function PerPersonTable({ open, line, restaurantKey, profile, onClose, onSave }) {
  if (!open || !line) return null;
  const item = getItemById(restaurantKey, line.itemId);
  if (!item) return null;

  // Build seat list — assigning portions to individuals based on profile + line.appliesTo logic
  // Demo simplification: for vegetarian line, fill with named vegetarians first, then "Guest"
  const seats = useMemo(() => {
    const named = [];
    if (line.itemId === "med-bowl") {
      const veg = profile.dietaryRestrictions.find(r => r.tag === "Vegetarian");
      const vegan = profile.dietaryRestrictions.find(r => r.tag === "Vegan");
      const treeNut = profile.dietaryRestrictions.find(r => r.tag === "Tree nut allergy");
      const indivs = veg?.individuals || [];
      for (let i = 0; i < line.qty; i++) {
        const name = indivs[i] || `Guest ${i + 1}`;
        const tags = [];
        if (vegan?.individuals?.includes(name)) tags.push("Vegan");
        if (treeNut?.individuals?.includes(name)) tags.push("Tree nut allergy");
        named.push({ index: i, name, tags });
      }
    } else if (line.itemId === "power-bowl") {
      const treeNut = profile.dietaryRestrictions.find(r => r.tag === "Tree nut allergy");
      // Fill with mostly Guest, with Sarah W appearing if in profile
      const namesToShow = treeNut?.individuals || [];
      for (let i = 0; i < line.qty; i++) {
        const namePicked = i < namesToShow.length ? namesToShow[i] : `Guest ${i + 1}`;
        const tags = [];
        if (treeNut?.individuals?.includes(namePicked)) tags.push("Tree nut allergy");
        named.push({ index: i, name: namePicked, tags });
      }
    } else {
      for (let i = 0; i < line.qty; i++) {
        named.push({ index: i, name: `Guest ${i + 1}`, tags: [] });
      }
    }
    return named;
  }, [line, profile]);

  return (
    <div style={{
      position: "fixed", inset: 0, background: T.overlay, zIndex: 100,
      display: "flex", alignItems: "center", justifyContent: "center", padding: 24,
      animation: "fadeIn 0.2s ease",
    }}
    onClick={onClose}>
      <div style={{
        background: T.card, borderRadius: 16, width: "100%", maxWidth: 880, maxHeight: "85vh",
        overflow: "hidden", display: "flex", flexDirection: "column",
        boxShadow: "0 20px 60px rgba(0,0,0,0.25)",
      }} onClick={e => e.stopPropagation()}>

        {/* Header */}
        <div style={{ padding: "16px 20px", borderBottom: `1px solid ${T.border}`, display: "flex", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 600, color: T.text, fontFamily: fontDisplay }}>
              Customize individual orders
            </div>
            <div style={{ fontSize: 12, color: T.textTertiary, marginTop: 2 }}>
              {line.qty} × {item.name} · profile dietary tags applied automatically
            </div>
          </div>
          <button onClick={onClose} style={{
            marginLeft: "auto", width: 30, height: 30, borderRadius: 8, border: "none",
            background: T.surface, color: T.text, fontSize: 16, cursor: "pointer",
          }}>✕</button>
        </div>

        {/* Defaults summary */}
        <div style={{ padding: "10px 20px", background: T.surface, borderBottom: `1px solid ${T.borderLight}` }}>
          <div style={{ fontSize: 10, fontWeight: 700, color: T.textTertiary, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6 }}>
            Group default
          </div>
          <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
            {Object.entries(line.modifiers).map(([key, val]) => (
              <span key={key} style={{
                fontSize: 11, padding: "3px 8px", borderRadius: 5,
                background: T.card, border: `1px solid ${T.border}`, color: T.textSecondary,
              }}>
                <strong style={{ color: T.text }}>{key}:</strong> {Array.isArray(val) ? val.join(", ") : val}
              </span>
            ))}
          </div>
        </div>

        {/* Per-seat rows */}
        <div style={{ overflowY: "auto", flex: 1, padding: "8px 0" }}>
          <table style={{ width: "100%", borderCollapse: "collapse", fontFamily: font }}>
            <thead style={{ position: "sticky", top: 0, background: T.card, zIndex: 1 }}>
              <tr style={{ borderBottom: `1px solid ${T.border}` }}>
                {["#", "Name", "Customizations", "Dietary tags", "Notes"].map(h => (
                  <th key={h} style={{ padding: "10px 16px", fontSize: 9, color: T.textTertiary, fontWeight: 700, letterSpacing: "0.06em", textTransform: "uppercase", textAlign: "left", fontFamily: fontDisplay }}>
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {seats.map((seat, i) => {
                const hasOverride = (line.perPersonOverrides || []).some(o => o.individual === seat.name);
                const override = line.perPersonOverrides?.find(o => o.individual === seat.name);
                const hasFlag = seat.tags.length > 0;
                return (
                  <tr key={seat.name} style={{
                    borderBottom: `1px solid ${T.borderLight}`,
                    background: hasFlag ? T.warningBg + "55" : "transparent",
                  }}>
                    <td style={{ padding: "10px 16px", fontSize: 11, color: T.textTertiary, fontFamily: fontMono }}>
                      {seat.index + 1}
                    </td>
                    <td style={{ padding: "10px 16px", fontSize: 12, color: T.text, fontWeight: 500 }}>
                      {seat.name}
                    </td>
                    <td style={{ padding: "10px 16px", fontSize: 11, color: T.textSecondary }}>
                      {hasOverride ? (
                        <span style={{ display: "inline-flex", alignItems: "center", gap: 5, padding: "2px 8px", borderRadius: 5, background: T.purpleBg, color: T.purple, fontWeight: 600 }}>
                          ✦ {override.removed ? `Removed: ${override.removed.join(", ")}` : "Customized"}
                          <span style={{ color: T.textTertiary, fontWeight: 400 }}>· {override.reason}</span>
                        </span>
                      ) : (
                        <span style={{ color: T.textTertiary, fontStyle: "italic" }}>Group default</span>
                      )}
                    </td>
                    <td style={{ padding: "10px 16px" }}>
                      {seat.tags.map(tag => (
                        <span key={tag} style={{
                          fontSize: 10, padding: "2px 6px", borderRadius: 4, marginRight: 4,
                          background: tag.includes("allergy") ? T.dangerBg : T.warningBg,
                          color: tag.includes("allergy") ? T.danger : T.warning,
                          fontWeight: 600,
                        }}>
                          {tag.includes("allergy") ? "⚠️" : "✦"} {tag}
                        </span>
                      ))}
                    </td>
                    <td style={{ padding: "10px 16px", fontSize: 11, color: T.textTertiary }}>
                      {seat.tags.includes("Tree nut allergy") && !hasOverride ? (
                        <span style={{ color: T.warning, fontStyle: "italic" }}>AI suggested: separate prep area</span>
                      ) : (
                        "—"
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        {/* AI suggestion banner */}
        <div style={{ padding: "10px 20px", background: T.brandLight, borderTop: `1px solid ${T.border}`, display: "flex", alignItems: "center", gap: 10 }}>
          <span style={{ fontSize: 14 }}>🤖</span>
          <div style={{ flex: 1, fontSize: 11, color: T.textSecondary, lineHeight: 1.5 }}>
            <strong style={{ color: T.brand }}>AI suggests:</strong> Add "separate prep area, no tree nut contamination" to special instructions for Sarah's bowl. The kitchen is notified at the line level.
          </div>
          <button onClick={() => { onSave?.({ acceptAI: true }); onClose(); }} style={{
            padding: "6px 14px", borderRadius: 8, border: "none", background: T.brand,
            color: "#fff", fontSize: 11, fontWeight: 600, cursor: "pointer", fontFamily: font,
          }}>
            Accept all
          </button>
        </div>
      </div>
    </div>
  );
}

// ─── Natural language edit preview card ───
