// ─── Compare carts side-by-side view ───
function CompareCartsView({ carts, profile, onPlaceOrder, onClose }) {
  const cols = Object.entries(carts).filter(([_, c]) => c && c.length > 0);
  if (cols.length === 0) return null;

  return (
    <div style={{
      position: "fixed", inset: 0, background: T.overlay, zIndex: 100,
      display: "flex", alignItems: "center", justifyContent: "center", padding: 24,
      animation: "fadeIn 0.2s ease",
    }}
    onClick={onClose}>
      <div style={{
        background: T.surface, borderRadius: 16, width: "100%", maxWidth: 980, maxHeight: "85vh",
        overflow: "hidden", display: "flex", flexDirection: "column",
        boxShadow: "0 20px 60px rgba(0,0,0,0.25)",
      }} onClick={e => e.stopPropagation()}>

        <div style={{ padding: "16px 20px", borderBottom: `1px solid ${T.border}`, background: T.card, display: "flex", alignItems: "center" }}>
          <div>
            <div style={{ fontSize: 16, fontWeight: 600, color: T.text, fontFamily: fontDisplay }}>
              Compare your carts
            </div>
            <div style={{ fontSize: 12, color: T.textTertiary, marginTop: 2 }}>
              {cols.length} carts built · pick the one to place
            </div>
          </div>
          <button onClick={onClose} style={{
            marginLeft: "auto", width: 30, height: 30, borderRadius: 8, border: "none",
            background: T.surface, color: T.text, fontSize: 16, cursor: "pointer",
          }}>✕</button>
        </div>

        <div style={{ overflowY: "auto", flex: 1, padding: 20 }}>
          <div style={{ display: "grid", gridTemplateColumns: `repeat(${cols.length}, 1fr)`, gap: 14 }}>
            {cols.map(([rkey, cart]) => {
              const r = MENUS[rkey];
              const totals = calcCartTotals(cart, r);
              const dietary = getDietaryCoverage(profile);
              const overBudget = totals.subtotal > profile.budgetTotal;
              // Hero item = highest-qty item in this cart, used as the visual representative
              const heroLine = [...cart].sort((a, b) => b.qty - a.qty)[0];
              const heroItem = heroLine ? getItemById(rkey, heroLine.itemId) : null;
              return (
                <div key={rkey} style={{
                  background: T.card, borderRadius: 14, border: `1px solid ${T.border}`,
                  display: "flex", flexDirection: "column", overflow: "hidden",
                }}>
                  {/* Hero image strip — visual choice driver, with brand-color backdrop */}
                  <div style={{ position: "relative", height: 140, overflow: "hidden", background: r.brandColor || T.surface }}>
                    {heroItem ? (
                      <MenuItemImage
                        item={heroItem}
                        fallbackIcon={r.icon}
                        size={140}
                        rounded={0}
                        mode="hero"
                        brandColor={r.brandColor}
                        brandColorAccent={r.brandColorAccent}
                      />
                    ) : (
                      <div style={{ height: "100%", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 56, color: "#fff", filter: "drop-shadow(0 2px 8px rgba(0,0,0,0.3))" }}>
                        {r.icon}
                      </div>
                    )}
                    {/* Bottom gradient for label legibility */}
                    <div style={{
                      position: "absolute", bottom: 0, left: 0, right: 0, height: 56,
                      background: `linear-gradient(to top, ${r.brandColor || "rgba(0,0,0,0.5)"}EE, transparent)`,
                      pointerEvents: "none",
                    }} />
                    {heroItem && (
                      <div style={{
                        position: "absolute", bottom: 10, left: 14, right: 14,
                        color: "rgba(255,255,255,0.95)",
                      }}>
                        <div style={{ fontSize: 9, fontWeight: 600, opacity: 0.85, letterSpacing: "0.08em", textTransform: "uppercase", marginBottom: 1 }}>
                          Featured pick
                        </div>
                        <div style={{ fontSize: 12, fontWeight: 600, textShadow: "0 1px 3px rgba(0,0,0,0.5)" }}>
                          {heroLine.qty} × {heroItem.name}
                        </div>
                      </div>
                    )}
                  </div>

                  <div style={{ padding: 16, display: "flex", flexDirection: "column", flex: 1 }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 14 }}>
                      <div style={{ width: 36, height: 36, borderRadius: 9, background: T.surface, border: `1px solid ${T.border}`, display: "flex", alignItems: "center", justifyContent: "center", fontSize: 18 }}>
                        {r.icon}
                      </div>
                      <div>
                        <div style={{ fontSize: 14, fontWeight: 600, color: T.text, fontFamily: fontDisplay }}>{r.name}</div>
                        <div style={{ fontSize: 10, color: T.textTertiary }}>{r.cuisine} · {r.baseRate}X base</div>
                      </div>
                    </div>

                    <div style={{ display: "flex", flexDirection: "column", gap: 8, marginBottom: 14 }}>
                      <ComparisonRow label="Total" value={`$${totals.subtotal.toFixed(2)}`} highlight={!overBudget} accent={overBudget ? T.danger : T.text} />
                      <ComparisonRow label="Per person" value={`$${(totals.subtotal / profile.headcount).toFixed(2)}`} accent={T.text} />
                      <ComparisonRow label="Bites earned" value={totals.totalBites.toLocaleString()} accent={T.brand} />
                      <ComparisonRow label="Items" value={`${cart.reduce((s, l) => s + l.qty, 0)} portions`} accent={T.text} />
                      <ComparisonRow label="Dietary" value={`${dietary.covered}/${dietary.total} covered`} accent={T.success} />
                      <ComparisonRow label="Variety" value={profile.recentRestaurantsByCuisine[r.cuisine] >= 8 ? "★★ recent" : "★★★★ fresh"} accent={T.text} />
                      <ComparisonRow label="Same-day" value={r.sameDay ? `Yes · until ${r.sameDayCutoff}` : "No"} accent={T.text} />
                    </div>

                    <div style={{ marginTop: "auto" }}>
                      <button onClick={() => onPlaceOrder(rkey)} style={{
                        width: "100%", padding: "10px 14px", borderRadius: 10, border: "none",
                        background: T.brand, color: "#fff", fontSize: 12, fontWeight: 600,
                        cursor: "pointer", fontFamily: font,
                      }}>
                        🍴 Place this order →
                      </button>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

function ComparisonRow({ label, value, accent, highlight }) {
  return (
    <div style={{
      display: "flex", justifyContent: "space-between", alignItems: "center",
      padding: "7px 10px", background: highlight ? T.successBg : T.surface, borderRadius: 7,
    }}>
      <span style={{ fontSize: 11, color: T.textSecondary, fontWeight: 500 }}>{label}</span>
      <span style={{ fontSize: 12, color: accent, fontWeight: 700, fontFamily: fontMono }}>{value}</span>
    </div>
  );
}

